import XCTest
import MurmurCore
@testable import MurmurWhisper

/// Downloads the tiny Whisper model and transcribes speech generated by macOS `say`.
/// Skipped unless `MURMUR_E2E=1`, because it needs the network and a few minutes. CI runs it
/// as a separate step.
final class WhisperEndToEndTests: XCTestCase {
    func testTinyModelTranscribesGeneratedSpeech() async throws {
        #if os(macOS)
        guard ProcessInfo.processInfo.environment["MURMUR_E2E"] == "1" else {
            throw XCTSkip("Set MURMUR_E2E=1 to run the end-to-end transcription test.")
        }
        let dir = FileManager.default.temporaryDirectory.appendingPathComponent("murmur-e2e-\(UUID().uuidString)")
        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: dir) }

        let aiff = dir.appendingPathComponent("speech.aiff")
        let wav = dir.appendingPathComponent("speech.wav")
        try run("/usr/bin/say", ["-o", aiff.path, "The quick brown fox jumps over the lazy dog. Murmur turns speech into text on your device."])
        try run("/usr/bin/afconvert", ["-f", "WAVE", "-d", "LEI16@16000", "-c", "1", aiff.path, wav.path])

        let downloader = WhisperKitDownloader(downloadBase: dir.appendingPathComponent("models"))
        let folder = try await downloader.download(.tiny) { _ in }
        let engine = WhisperKitEngine(modelFolder: folder)
        let output = try await engine.transcribe(
            audioURL: wav, duration: 0, options: TranscriptionOptions(language: "en"), onProgress: { _ in }
        )

        print("E2E transcript: \(output.text)")
        for segment in output.segments { print("E2E segment \(segment.start)-\(segment.end): \(segment.text)") }
        let text = output.text.lowercased()
        let hits = ["quick", "brown", "fox", "lazy", "dog", "speech", "text"].filter { text.contains($0) }
        XCTAssertGreaterThanOrEqual(hits.count, 3, "transcript was: \(output.text)")
        XCTAssertFalse(output.segments.isEmpty)
        XCTAssertEqual(output.language, "en")
        #else
        throw XCTSkip("macOS only.")
        #endif
    }

    #if os(macOS)
    private func run(_ path: String, _ arguments: [String]) throws {
        let process = Process()
        process.executableURL = URL(fileURLWithPath: path)
        process.arguments = arguments
        try process.run()
        process.waitUntilExit()
        XCTAssertEqual(process.terminationStatus, 0, "\(path) failed")
    }
    #endif
}
